/* the glyph number of ch in f, -1 = not in the face */
static int32_t glyph_at(const aafont_t *f, uint32_t ch)
{
    uint32_t i;
    if (ch >= f->first && ch <= f->last)
        return (int32_t)(ch - f->first);
    for (i = 0; i < f->nex; i++)
        if (f->ex[i] == ch)
            return (int32_t)(f->last - f->first + 1u + i);
    return -1;
}

/* a key of a recorded note is up: the hold ends with the last one. (2.0, #25) Held notes started on different steps: each
 * ends with its own key; tied into the step playing, a release before its middle takes it out of it */
static void rec_release(track_t *t, uint32_t note)
{
    uint32_t i, k = 0, ti = trk_index(t), tm = 0, out = 0, x, lo;
    int early = t->seq_idx == t->rh_last &&
                t->seq_pos < step_samples(t, div_samples((uint32_t)t->p[P_SDIV]), t->seq_idx) / 2u;
    for (i = 0; i < t->rh_n; i++)
        if (t->rh_note[i] != note) {
            rec_n[ti][k] = rec_n[ti][i];
            tm |= ((rec_tm[ti] >> i) & 1u) << k;
            t->rh_note[k++] = t->rh_note[i];
        } else {
            out = (rec_tm[ti] >> i) & 1u;
        }
    if (k == t->rh_n)
        return;                                     /* not one of them */
    rec_tm[ti] = (uint8_t)tm;
    if (rec_mix[ti]) {
        step_t *s = &t->step[t->rh_last];
        t->rh_n = (uint8_t)k;
        for (x = 0; out && early && x < s->n && s->note[x] != note; x++)
            ;
        if (out && early && x < s->n) {             /* (its tie out of the step again, the ones above down a place) */
            lo = (1u << x) - 1u;
            for (; x + 1u < s->n; x++)
                s->note[x] = s->note[x + 1u];
            s->note[--s->n] = 0;
            s->acc = (uint8_t)((s->acc & lo) | ((s->acc >> 1) & ~lo));
            if (!s->n && !s->hit)
                s->time = ST_REST;
        }
        return;
    }
    if ((t->rh_n = (uint8_t)k))
        return;                                     /* others still held */
    if (t->rh_ties && early)
        t->step[t->rh_last] = t->rh_bak;            /* released early in it: not held into this step */
}

/* where track t is now, as REC places a note: *pass and the step; *feel: its NUDGE there (seq.c feel_of) */
static uint32_t take_stamp(const track_t *t, uint32_t *pass, int32_t *feel)
{
    uint32_t len = t->p[P_SLEN] > 0 ? (uint32_t)t->p[P_SLEN] : 1u, idx = t->seq_idx % len, next = 0;
    uint32_t pos = t->seq_pos > TAKE_LAT ? t->seq_pos - TAKE_LAT : 0u;
    *pass = take_pass[trk_index(t)];
    if (t->seq_pos < 0x7FFFFFFFu && pos > step_samples(t, div_samples((uint32_t)t->p[P_SDIV]), t->seq_idx) / 2u &&
        t->p[P_DIR] != DIR_RAND) {                    /* (0x7FFFFFFF: PLAY, before the first block; RAND: no next) */
        if (seq_pass_last(t, len))
            ++*pass;                                  /* past the middle of the pass's last step: the next pass */
        idx = seq_peek(t, len);                       /* the next step in its direction (seq.c) */
        next = 1;
    }
    *feel = t->seq_pos < 0x7FFFFFFFu ? feel_of(t, pos, next) : 0;
    return idx;
}

static void arp_off(track_t *t)                  /* the sounding arp note(s) end (a recorded one too) */
{
    if (t->arp_ch[0] | t->arp_ch[1] | t->arp_ch[2])
        arp_chord_off(t, rec_on(t));
    arp_note_off(t, t->arp_note);
    if (rec_on(t))
        rec_release(t, t->arp_note);
    else
        take_note(t, t->arp_note, 0);               /* (Skiff: TAKES) */
    t->arp_note = 0;
}

