/* a CC sets parameter id of track t as a knob would: 0..127 over its range */
static void midi_cc_set(track_t *t, uint32_t id, uint32_t value)
{
    const param_desc_t *d = param_desc_of(eng_idx(t->eng_req), id);
    int32_t v = d->min + ((int32_t)value * (d->max - d->min) + 63) / 127;
    if (d->max <= d->min || t->p[id] == v)
        return;
    t->p[id] = (int16_t)v;
    (void)motion_capture(t, id, (int16_t)v);
}

/* the delay's TIME (params.c N_DTIME): N_DIV's ten (div_samples), then (Skiff 1.3, from Felucca 1.5.1) the dotted 1/8D
 * 1/16D 1/4D (10, 11, 12: 3/4, 3/8, 3/2 of a quarter); at most DLY_LEN - 1 samples: a long one clamps at slow tempos */
static const uint8_t DIV_DOT[3] = {2, 3, 1};           /* 3 quarters >> this */
static uint32_t delay_samples(void)
{
    uint32_t d = (uint32_t)song.g[G_DTIME];
    uint32_t s = d - 10u < 3u ? (beat_samples() * 3u) >> DIV_DOT[d - 10u] : div_samples(d);
    return s < 16u ? 16u : s >= DLY_LEN ? DLY_LEN - 1u : s;
}

static void e0_chunk(void)
{
    uint32_t n = usb.e0_left > 64u ? 64u : usb.e0_left, i;
    int last;
    for (i = 0; i < n; i++)
        ep0buf[i] = usb.e0_src[i];
    fm1_usb_ep0_send(ep0buf, n);
    usb.e0_src += n;
    usb.e0_left = (uint16_t)(usb.e0_left - n);
    last = usb.e0_left == 0 && !(n == 64u && usb.e0_zlp);
    if (usb.e0_left == 0 && n == 64u)
        usb.e0_zlp = 0;
    sie_wr(S_INDEX, 0);
    sie_wr(S_CSR0, last ? 0x0A : 0x02);
    if (last)
        usb.e0_tx = 0;
}

static void e0_send(const uint8_t *p, uint16_t len, uint16_t wlen)
{
    if (len > wlen)
        len = wlen;
    usb.e0_src = p;
    usb.e0_left = len;
    usb.e0_zlp = (len < wlen) && (len % 64u == 0);
    usb.e0_tx = 1;
    sie_wr(S_INDEX, 0);
    sie_wr(S_CSR0, 0x40);
    e0_chunk();
}

static uint8_t fm1_p33_read(uint32_t a)
{
    uint8_t v;
    fm1__p33_cs(a);
    fm1__p33_xfer((uint8_t)(0x80u | ((a >> 8) & 3u)));
    fm1__p33_xfer((uint8_t)a);
    v = fm1__p33_xfer(0x5E);
    FM1_P33_CON &= ~((1u << 0) | (1u << 8));
    return v;
}

static uint32_t st_crc32(const void *p, uint32_t n)   /* zlib CRC-32, 4 bits per step */
{
    static const uint32_t T[16] = {
        0x00000000u, 0x1DB71064u, 0x3B6E20C8u, 0x26D930ACu, 0x76DC4190u, 0x6B6B51F4u, 0x4DB26158u, 0x5005713Cu,
        0xEDB88320u, 0xF00F9344u, 0xD6D6A3E8u, 0xCB61B38Cu, 0x9B64C2B0u, 0x86D3D2D4u, 0xA00AE278u, 0xBDBDF21Cu};
    const uint8_t *b = p;
    uint32_t c = 0xFFFFFFFFu;
    while (n--) {
        c ^= *b++;
        c = (c >> 4) ^ T[c & 15u];
        c = (c >> 4) ^ T[c & 15u];
    }
    return ~c;
}

/* (#21) smx_load (eng_sample.c smp_user_scan): slot k was read and is valid: its stored mix, if it is its header's */
static void smx_store_load(uint32_t k)
{
    smx_rec_t c;
    if (!slc_rec_room(k))                            /* (its last sector is the sample's) */
        return;
    memcpy(&c, smp_user_xip(k) + SMX_REC_OFF, sizeof c);
    if (c.chk == smx_chk(k, &c))                     /* (a value out of 0..127: LEVEL full, the sends capped: dsp.c */
        memcpy(usr_mix[k], c.mix, sizeof c.mix);     /* vmod_level, fx.c smx_render) */
}

/* b, n bytes of a stored settings record: SKS1, or (before 2.0) PER4 (.. PER1 with FELUCCA_LEGACY). Normalized in place;
 * 1 = current, 2 = migrated, 0 = invalid. An SKS1 is read as the PER4 it names (Skiff's: its mark), its room kept */
static int settings_import(void *b, int n)
{
    sks_t *s = (sks_t *)b;
    persist_t p;
    if (n != (int)sizeof *s || s->magic != SKS_MAGIC)
        return settings_import_per((persist_t *)b, n);
    p.magic = PERSIST_MAGIC; p.palette = s->palette; p.lowcut = s->lowcut; p.zoom = s->zoom; p.bold = s->bold;
    p.panel = s->panel;
    memcpy(p.favorites.factory, s->fav, sizeof s->fav);
    memcpy(p.favorites.factory[15], &s->s, sizeof s->s);
    p.favorites.factory[15][24] = 0xA5u;
    memcpy(&p.favorites.factory[14][8], s->cpal_cols, sizeof s->cpal_cols);
    memcpy(&p.favorites.factory[ENGI_DIGITAL][2], s->ml, sizeof s->ml);
    p.favorites.user = s->fav_user; p.favorites.filter = s->fav_filter;
    (void)settings_import_per(&p, sizeof p);
    s->palette = p.palette;
    sks_pack(s, (const uint8_t (*)[32])p.favorites.factory, p.favorites.user, p.favorites.filter);
    return 1;
}

/* the descriptor of parameter id for engine e without the engine's desc hook (the device display
 * only; range and default are the same): what the editor protocol, user presets and projects use */
static const param_desc_t *param_desc_of(uint32_t e, uint32_t id)
{
    return id >= P_E0 ? &ENGINES[e]->edit[id - P_E0] : &TP[id];
}

/* 12 stored name bytes -> d (PROJ_NAME_LEN + 1): up to the first 0, upper case; a byte outside 32..126 makes it
 * no name (a damaged tail never refuses the project) */
static uint32_t proj_name_get(char *d, const uint8_t *s)   /* its length */
{
    uint32_t i;
    for (i = 0; i < PROJ_NAME_LEN && s[i]; i++) {
        if (s[i] < 32u || s[i] > 126u) { i = 0; break; }
        d[i] = (char)(s[i] >= 'a' && s[i] <= 'z' ? s[i] - 32u : s[i]);
    }
    d[i] = 0;
    return i;
}

/* (Skiff phase 6) tracks from .. NTRK - 1 as at power-on, for a format holding fewer: the engine's defaults, its
 * power-on sound (PROJ_DEF_SOUND: project_restore_runtime loads it), no steps, the init patch, no list */
static void proj_power_on_trk(project_t *q, uint32_t i)
{
    uint32_t k;
    for (k = 0; k < P_COUNT; k++)
        q->t[i].p[k] = param_desc_of(trk_def_engine(i), k)->def;
    q->t[i].engine = (uint8_t)trk_def_engine(i);
    q->t[i].preset = PROJ_DEF_SOUND;
#if FELUCCA_LEGACY
    for (k = 0; k < NSTEP; k++)
        q->t[i].step[k].time = ST_REST;
#endif
    memcpy(q->fm6[i], FM6_INIT, FM6_PACKED);
}

/* q -> an SKF2 or (Skiff phase 6) SKF3 record, format f (its steps and motion not: they are the patterns'): 0 for a
 * value no format can hold, or a format of more tracks than this firmware has. Its first f->nt tracks, the first f->sc
 * scene bytes: SKF2 holds four tracks, their scenes. (2.0) SKF4: proj_pack4 */
static int proj_pack2(project_store_t *out, const project_t *q, const proj_fmt_t *f)
{
    uint8_t *b = out->raw;
    uint32_t pos = 68u, t, i, sum;
    if (f == &PROJ_SKF4) return proj_pack4(out, q);
    if (f->nt > NTRK || f->sc > PROJ_SCENES) return 0;
    for (t = 0; t < f->nt; t++)
        for (i = 0; i < FM6_PACKED; i++)
            if (q->fm6[t][i] > 127u) return 0;
    if (!proj_ent_ok(q)) return 0;
    memset(out, 0, sizeof *out); memcpy(b, &f->magic, 4); memcpy(b + 4, &f->size, 4);
    memcpy(b + 8, q->g, sizeof q->g); b[62] = q->sel; b[63] = q->parts; b[64] = q->phys; b[65] = q->song;
    b[66] = PROJ_NP;
    for (t = 0; t < f->nt; t++) {
        if (!proj_np_put(b + pos, q->t[t].p)) return 0;   /* ((phase 9) PROJ_NP, by count) */
        pos += PROJ_NP;
        b[pos++] = q->t[t].engine; b[pos++] = q->t[t].preset;
    }
    memcpy(b + pos, q->ent, f->nt * NENT * 2u); pos += f->nt * NENT * 2u;
    memcpy(b + pos, q->cur, f->nt); pos += f->nt;
    memcpy(b + pos, q->scene, f->sc); pos += f->sc;
    if (pos > PROJ_HEAD_END(f)) return 0;
    if (f->dx) {                                      /* ((phase 9) the parameters past PROJ_NP: the PX block, if one */
        uint32_t any = 0, j;                          /* is not its default) */
        for (t = 0; t < f->nt; t++)
            for (j = 0; j < PROJ_NX; j++) {
                int32_t v = q->t[t].p[PROJ_NP - 8u + j];
                if (v < -64 || v > 127) return 0;
                any |= v != TP[PROJ_NP - 8u + j].def;
            }
        if (any) {
            uint8_t *x = b + PROJ_PX_AT(f);
            x[0] = PROJ_PX_MARK;
            x[1] = (uint8_t)PROJ_NX;
            for (t = 0; t < f->nt; t++)
                for (j = 0; j < PROJ_NX; j++)
                    x[2u + t * PROJ_NX + j] = (uint8_t)(q->t[t].p[PROJ_NP - 8u + j] + 64);
        }
    }
    if (f->dx && q->dx_on && dx_kit_ok(q->dx)) {     /* (phase 7) the DRUM-X kit (none: 0, the factory's) */
        b[PROJ_DX_AT(f)] = PROJ_DX_MARK;
        memcpy(b + PROJ_DX_AT(f) + 1u, q->dx, sizeof q->dx);
    }
    memcpy(b + PROJ_FM6_AT(f), q->fm6, f->nt * FM6_PACKED);
    {
        char n[PROJ_NAME_LEN + 1u];
        memcpy(b + PROJ_NAME_AT(f), n, proj_name_get(n, (const uint8_t *)q->name));
    }
    sum = proj_hash(b, f->size - 4u); memcpy(b + f->size - 4u, &sum, 4);
    return 1;
}

/* an ellipse rx x ry turned by rot (a turn 2^32) round (cx, cy), n segments */
static void qk_ellipse(int32_t cx, int32_t cy, int32_t rx, int32_t ry, uint32_t rot, uint16_t c, uint32_t n)
{
    int32_t cr = QK_COS(rot), sr = QK_SIN(rot), px = 0, py = 0;
    uint32_t k;
    for (k = 0; k <= n; k++) {
        uint32_t ph = k * (0xFFFFFFFFu / n);   /* (32-bit: no 64-bit division in the firmware) */
        int32_t ex = rx * QK_COS(ph) / 32767, ey = ry * QK_SIN(ph) / 32767;
        int32_t x = cx + (ex * cr - ey * sr) / 32767, y = cy + (ex * sr + ey * cr) / 32767;
        if (k)
            cv_line(px, py, x, y, c);
        px = x;
        py = y;
    }
}

static void step_clear(step_t *st)
{
    st->n = 0;
    st->time = ST_REST;
    st->flags = 0;
    st->vel = 0;
    st->hit = st->acc = 0;
    st->probability = 0;
    st->cond = 0;                                /* (Skiff: its trig condition too, its NUDGE) */
    st->nudge = 0;
}

static void motion_snapshot_track(track_t *t, motion_store_t *out)
{
    uint32_t f = motion_guard(), k = trk_index(t), i;
    memset(out, 0, sizeof *out);
    out->on = motion.on & (uint8_t)(1u << k);
    for (i = 0; i < motion.count; i++)
        if ((motion.event[i].place >> 6) == k) out->event[out->count++] = motion.event[i];
    motion_unguard(f);
}

/* a retired preset kept as an alias, so stored preset numbers stay valid: SAMPLE 1, once TRANH, is PIANO
 * (tools/gen_samples.py SMP_SET_ORIG). It loads as the original; browsing skips it. -> the preset k stands for.
 * (SAMPLE 4, once PERC: apply_preset_to loads it as DRUM; (Skiff phase 9) SAMPLE's variations follow it, so it is an
 * alias among the presets, skipped as 1 is) */
static uint32_t preset_orig(const engine_t *e, uint32_t k)
{
    return e->presets == SMP_PRESET_TABLE && k < SMP_NSETS ? SMP_SET_ORIG[k] : k;
}

/* track tr's patch was just put in as its own (a project, a user preset, the editor, a conversion): an FM6 track's
 * SLOT shows the factory patch it equals unchanged (F n; the SLOT it had first), else OWN; nothing reloads over it
 * (fm6_poll) */
static void fm6_adopt(uint32_t tr)
{
    track_t *t = &trk[tr % NTRK];
    int32_t s = t->p[P_E7];
    tr %= NTRK;
    fm6_own_ok &= (uint8_t)~(1u << tr);
    if (t->eng_req == ENGI_FM6)
        t->p[P_E7] = (int16_t)(s = fm6_match(fm6_patch[tr], s));
    fm6_slot[tr] = (uint8_t)s;
}

/* icon id's cell number at *size 12, 16 or 24 px (missing at 16 or 24: its 12 px cell, *size 12), -1: none */
static int32_t icon_cell(uint32_t *size, uint32_t id)
{
    const uint8_t *idx = *size == 24u ? AI24_IDX : *size == 16u ? AI16_IDX : AI12_IDX;
    if (id >= ICON_COUNT)
        return -1;
    if (idx[id] == 0xFFu) {
        if (*size == 12u || AI12_IDX[id] == 0xFFu)
            return -1;
        *size = 12u;
        idx = AI12_IDX;
    }
    return idx[id];
}

