static void settings_poll(void)
{
#if FELUCCA_FLASH
    sks_t p;
#if FELUCCA_SLICE
    slc_store_poll();                              /* SLICE's slices edited on the SLICES page */
#endif
    if (!persist_pending || !flash_ok || transport_busy() ||
        (persist_pending == 2u && (uint32_t)(fm1_ms - persist_retry_ms) < 1000u))
        return;
    p = persist_saved;
    settings_export(&p);
    if (!memcmp(&p, &persist_saved, sizeof p)) {
        persist_pending = 0;
        return;                                    /* unchanged: no erase cycle */
    }
    if (st_save(OBJ_SETTINGS, &p, sizeof p) == 0) {
        persist_saved = p;
        persist_pending = 0;
    } else {
        persist_pending = 2;
        persist_retry_ms = fm1_ms;
    }
#endif
}

/* pattern id's record as it is now -> r: its waiting copy, else flash's: 0, 1 none (empty, or one no firmware wrote) */
static int pat_read(uint32_t id, uint8_t *r)
{
    uint32_t i = pend_at(id), c = bk_chunk(id);
    if (i < PEND_N)
        memcpy(r, pend_rec[i], BK_REC);
    else if (!bk.len[id % BK_POOL] || !bk.sect[c] ||
             bk_read(bk_sector(bk.sect[c] - 1u) + 256u + id % BK_PER * BK_REC, r, BK_REC))
        return 1;
    return bk_ver(r[0]) && (r[7] & 127u) <= MOTION_MAX ? 0 : 1;
}

/* what an autosave would hold, hashed (no copy, no RAM): project_capture's values */
static uint32_t autosave_sig(void)
{
    uint32_t h = 2166136261u, i, j;
    for (i = 0; i < NTRK; i++) {
        const track_t *t = &trk[i];
        for (j = 0; j < P_COUNT; j++) {
            int16_t v = motion_base_value(t, j);
            h = as_mix(h, &v, sizeof v);
        }
        h = as_mix(h, &t->eng_req, 1);
        h = as_mix(h, &t->preset, 1);
        h = as_mix(h, &t->user, 1);                   /* ((2.0, #20) the user sound it is on: SKF4 holds it) */
        h = as_mix(h, t->step, sizeof t->step);
        h = as_mix(h, fm6_patch[i], sizeof fm6_patch[i]);
    }
    h = as_mix(h, dx_kit, sizeof dx_kit);             /* (phase 7) the DRUM-X kit */
    for (i = 0; i < G_COUNT; i++)                       /* ((Skiff U3) not the unit's CLOCK MIDI IN TUNE, ui.c) */
        if (i != G_SLOT && i != G_NAME && i != G_LOAD && i != G_SAVE && !unit_g_id(i))
            h = as_mix(h, &song.g[i], sizeof song.g[i]);
    h = as_mix(h, &motion, sizeof motion);
    h = as_mix(h, &lists, sizeof lists);              /* (phase 5) the lists, the patterns the tracks are on */
    h = as_mix(h, trk_pid, sizeof trk_pid);
    i = (ui_prefs & PREF_RESTORE_OFF) != 0;           /* (RESTORE LAST back ON: a round, the project written) */
    h = as_mix(h, &i, sizeof i);
    return as_mix(h, proj_name, sizeof proj_name);
}

/* a name from the editor -> b (PROJ_NAME_LEN + 1), upper case; 0: refused (too long, a byte outside 32..126) */
static int ed_proj_name_in(const uint8_t *a, uint32_t n, char *b)
{
    uint32_t i;
    if (n && !a[n - 1u])
        n--;
    if (n > PROJ_NAME_LEN)
        return 0;
    for (i = 0; i < n; i++) {
        if (a[i] < 32u || a[i] > 126u)
            return 0;
        b[i] = (char)(a[i] >= 'a' && a[i] <= 'z' ? a[i] - 32u : a[i]);
    }
    b[n] = 0;
    return 1;
}

/* bk_buf -> chunk c's next copy, the commit record last, then read back: 0 written */
static int bk_write(uint32_t c)
{
    uint32_t to = bk_free(), base, off;
    bk_hdr_t h, chk;
    int rc;
    if (to == BK_NONE)
        return -1;
    base = bk_sector(to);
    if ((rc = bk_erase(base)) != 0)
        return rc;
    for (off = 0; off < BK_LEN; off += 256u)
        if ((rc = bk_prog(base + 256u + off, bk_buf + off, BK_LEN - off > 256u ? 256u : BK_LEN - off)) != 0)
            return rc;
    h.magic = BK_MAGIC;
    h.chunk = c;
    h.seq = bk.top + 1u;
    h.len = BK_LEN;
    h.sum = proj_hash(bk_buf, BK_LEN);
    h.rsv[0] = h.rsv[1] = 0xFFFFFFFFu;
    h.hsum = proj_hash(&h, sizeof h - 4u);
    if ((rc = bk_prog(base, &h, sizeof h)) != 0)
        return rc;
    if (bk_head(to, &chk) || memcmp(&chk, &h, sizeof h) || bk_body(to, &chk))
        return -7;                                 /* (a part that does not keep what it is given: not SAVED) */
    bk.sect[c] = (uint8_t)(to + 1u);
    bk.top = h.seq;
    bk.next = (uint8_t)((to + 1u) % BK_NSECT);
    bk.gen++;
    return 0;
}

