/* a 2 px stroke from (xa, ya) to (xb, yb): 2 x 2 blocks along it */
static void cr_stroke(int32_t xa, int32_t ya, int32_t xb, int32_t yb, uint16_t c)
{
    int32_t dx = xb - xa, dy = yb - ya, n = dx < 0 ? -dx : dx, m = (dy < 0 ? -dy : dy) / 2, k;
