/* a * k / 65536 without 64-bit: a up to 2^31, k Q16 */
static inline int32_t mulq16(int32_t a, uint32_t k)
{
    return (int32_t)(((a >> 16) * (int32_t)k) + (int32_t)(((uint32_t)(a & 0xFFFF) * k) >> 16));
}

static void wheel_note_on(track_t *t, voice_t *v)
{
    uint32_t vi = (uint32_t)(v - t->v) % NVOICE, k, held = 0;
    drw_vc_t *V = &((drw_vc_t *)eng_part(t))[vi];   /* (Skiff: the part's shared area, engines.c) */
    for (k = 0; k < NVOICE; k++)                        /* single trigger: another key of the part held? */
        if (&t->v[k] != v && t->v[k].active && t->v[k].gate && t->v[k].stage != 4u)
            held = 1;
    if (!V->init) {                                     /* the wheels: spread start phases, then free running */
        for (k = 0; k < DRW_NP; k++)
            V->ph[k] = (k * 0x9E3779B9u) ^ (vi * 0x7F4A7C15u);
        V->nz = 0x13579BDF + (int32_t)vi;
        V->init = 1;
    }
    V->perc = held ? 0 : 32767;
    V->clk = 32767;
    V->hp = 0;
    V->gate = 1;
}

/* p16 -> a bilinear one-pole high-pass (s / (s + w), not prewarped): y = g (x - x1) + p y1, g and p in Q14 */
static void dv_hp1(int32_t *g, int32_t *p, int32_t p16)
{
    uint32_t inc = p16 > 1900 ? DV_P16(clamp(p16, 0, 2239) - 192) << 1 : DV_P16(p16);   /* (above the table: an octave
                                                          * down, doubled) */
    int32_t u = (int32_t)(((inc >> 17) * 205887u) >> 15);   /* w / 2fs = pi f / fs, Q16 */
    *g = (65536 << 14) / (65536 + u);
    *p = (65536 - u) * 16384 / (65536 + u);
}

/* -------------------------------------------------------------- macros --- */
/* RATIO, MOD ENV and VEL MOD (e: P_E0..) on the modulators of patch p in algorithm alg (0..31), as they play: the
 * audio ISR's copy (fm6_sync) and (FM6 LAB) the editor's graph (ui_fm6.c) */
static void fm6_macro(uint8_t *p, uint32_t alg, const int16_t *e)
{
    uint32_t car = fm6_carriers(alg), k, j;
    int32_t meg = clamp(e[4], -64, 63) * 40 / 64;           /* MEG: rate steps (+ slower) */
    for (k = 0; k < 6u; k++) {
        uint8_t *op = p + k * FP_OP;
        if ((car >> k) & 1u)
            continue;
        if (!op[FP_MODE])
            op[FP_FC] = (uint8_t)clamp(op[FP_FC] + e[3], 0, 31);
        for (j = 0; j < 4u; j++)
            op[FP_R1 + j] = (uint8_t)clamp(op[FP_R1 + j] - meg, 0, 99);
        op[FP_KVS] = (uint8_t)clamp(op[FP_KVS] + e[5], 0, 7);
    }
}

/* operator op's envelope at a note-on of MIDI note `note`, velocity vel: its output level with the key's level scaling
 * and the velocity, its rate scaling. The note's, and (FM6 LAB) the editor's: ui_fm6.c draws what plays */
static void fm6_op_env_init(fm6_env_t *e, const uint8_t *op, int32_t note, int32_t vel)
{
    int32_t ol = fm6_scaleout(op[FP_OL]) + fm6_scale_level(note, op);
    ol = (ol > 127 ? 127 : ol) << 5;
    ol += fm6_scale_vel(vel, op[FP_KVS]);
    fm6_env_init(e, op, ol < 0 ? 0 : ol, fm6_scale_rate(note, op[FP_RS]));
}

/* a straight segment with the brush; its colour per column from sh[shade[column]] (or c when shade is 0); w < 0: dotted
 * (QUARK: a bubble chamber's track), a dot every 3 px */
static void fm_seg(int32_t xa, int32_t ya, int32_t xb, int32_t yb, int32_t w, uint16_t c, const uint8_t *shade,
                   const uint16_t *sh)
{
    int32_t n = 2 * ((xb > xa ? xb - xa : xa - xb) > (yb > ya ? yb - ya : ya - yb) ? (xb > xa ? xb - xa : xa - xb)
                                                                                   : (yb > ya ? yb - ya : ya - yb)), j;
    int dot = w < 0;
    if (dot)
        w = -w;
    if (n < 1)
        n = 1;
    for (j = 0; j <= n; j++) {
        int32_t x = xa + (xb - xa) * j / n, y = ya + (yb - ya) * j / n;
        if (!dot || j / 2 % 3 == 0)
            fm_brush(x, y, w, shade ? sh[shade[clamp(x - FM_X0, 0, FM_XW - 1)]] : c);
    }
}

static int32_t fm_lvy(int32_t v)
{
    return FM_GY + 4 + clamp(FM_TOP - v, 0, FM_SPAN) * (FM_GH - 9) / FM_SPAN;
}

static void span_mod_dst(const card_span_t *sp, int32_t v, char *val, const char **unit)   /* MOD's DEST: the track's */
{
    str_cpy(val, mod_dst_name((const track_t *)sp->p, v), 12);
    *unit = "";
}
